-- Recipe translations for production (2026-11-20): the 40 Russian and Hebrew translations from the local database.
-- Repeat-safe, no BEGIN/COMMIT (Replit's SQL box rejects them). Run it in Replit → Production Database → My Data → "+",
-- or in the Replit Shell: psql "$PROD_URL" -v ON_ERROR_STOP=1 --single-transaction -f script/prod-recipe-translations.sql
-- Adds a translation only for a recipe production has; never changes recipes or existing translations.
-- A translation whose ingredient or step count differs from production's recipe is stored but not shown (recipe-translation.ts).

-- Migration 0021, repeat-safe.
ALTER TABLE "recipes" ADD COLUMN IF NOT EXISTS "language" varchar(2);
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'recipes_language_check') THEN
    ALTER TABLE "recipes" ADD CONSTRAINT "recipes_language_check" CHECK ("recipes"."language" IS NULL OR "recipes"."language" ~ '^[a-z]{2}$');
  END IF;
END $$;
CREATE TABLE IF NOT EXISTS "recipe_translations" (
  "recipe_id" varchar NOT NULL,
  "language" varchar(2) NOT NULL,
  "title" text NOT NULL,
  "ingredients" text[] NOT NULL,
  "steps" text[] NOT NULL,
  "translated_by" varchar(8) NOT NULL,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  CONSTRAINT "recipe_translations_recipe_id_language_pk" PRIMARY KEY("recipe_id","language"),
  CONSTRAINT "recipe_translations_recipe_id_recipes_id_fk" FOREIGN KEY ("recipe_id") REFERENCES "public"."recipes"("id") ON DELETE cascade ON UPDATE no action,
  CONSTRAINT "recipe_translations_language" CHECK ("language" IN ('en','ru','he')),
  CONSTRAINT "recipe_translations_translated_by" CHECK ("translated_by" IN ('ai','person'))
);

INSERT INTO "recipe_translations" ("recipe_id", "language", "title", "ingredients", "steps", "translated_by")
SELECT v.* FROM (VALUES
  ('tablewise:catalog:v1:aubergine-parmigiana', 'he', 'פרמיג''אנה חצילים', '{"3 חצילים גדולים, פרוסים לאורכם","5 כפות שמן זית, מחולקות","1 בצל, קצוץ דק","3 שיני שום, כתושות","800 גרם עגבניות קצוצות משומרות","1 כף רסק עגבניות","1 כפית סוכר","0.75 כפית מלח","20 גרם בזיליקום טרי, עלים קרועים","250 גרם מוצרלה, מסוננת וקרועה","60 גרם גבינה קשה צמחונית, מגוררת דק"}'::text[], E'{"חממו את התנור ל-220 מעלות (200 מעלות בטורבו). פרסו את החצילים לפרוסות בעובי של כ-1 ס\\"מ, הברישו את שני הצדדים ב-4 כפות מהשמן, פזרו על שתי תבניות וצלו 20–25 דקות, תוך היפוך אחד, עד שהם רכים וזהובים.","בינתיים חממו את שארית השמן בסיר על אש בינונית. בשלו את הבצל 6–8 דקות עד שהוא מתרכך, ואז הוסיפו את השום לדקה אחת.","הוסיפו את העגבניות, רסק העגבניות, הסוכר והמלח ובשלו על אש קטנה 15 דקות עד שהרוטב מסמיך. ערבבו פנימה את רוב הבזיליקום.","הנמיכו את התנור ל-190 מעלות (170 מעלות בטורבו). בתבנית אפייה סדרו שכבה של מעט רוטב, ואז חצילים, מוצרלה ומעט גבינה קשה. חזרו על השכבות וסיימו ברוטב ובשארית הגבינה הקשה.","אפו 30–35 דקות, עד שהתבשיל מבעבע והחלק העליון זהוב. תנו לו לנוח 10 דקות, פזרו את שארית הבזיליקום והגישו."}'::text[], 'ai'),
  ('tablewise:catalog:v1:aubergine-parmigiana', 'ru', 'Баклажаны по-пармски (пармиджана)', '{"3 крупных баклажана, нарезанных вдоль","5 ст. л. оливкового масла, разделить","1 луковица, мелко нарезанная","3 зубчика чеснока, раздавленных","800 г консервированных резаных томатов","1 ст. л. томатного пюре","1 ч. л. сахара","0,75 ч. л. соли","20 г свежего базилика, листья порвать","250 г моцареллы, обсушить и порвать","60 г вегетарианского твёрдого сыра, мелко натереть"}'::text[], '{"Разогрейте духовку до 220 °C (200 °C с конвекцией). Нарежьте баклажаны ломтиками толщиной около 1 см, смажьте с обеих сторон 4 ст. л. масла, разложите на два противня и запекайте 20–25 минут, один раз перевернув, до мягкости и золотистого цвета.","Тем временем разогрейте оставшееся масло в сотейнике на среднем огне. Готовьте лук 6–8 минут до мягкости, затем добавьте чеснок на 1 минуту.","Добавьте томаты, томатное пюре, сахар и соль и тушите 15 минут, пока соус не загустеет. Вмешайте бо́льшую часть базилика.","Уменьшите температуру духовки до 190 °C (170 °C с конвекцией). В форме для запекания выложите слоями немного соуса, затем баклажаны, моцареллу и немного твёрдого сыра. Повторите слои, закончив соусом и оставшимся твёрдым сыром.","Запекайте 30–35 минут, пока не забулькает и верх не станет золотистым. Дайте постоять 10 минут, посыпьте оставшимся базиликом и подавайте."}'::text[], 'ai'),
  ('tablewise:catalog:v1:fish-pie', 'he', 'פשטידת דגים', E'{"1 ק\\"ג תפוחי אדמה קמחיים, קלופים וחתוכים לגושים","90 גרם חמאה, מחולקת","600 מ\\"ל חלב מלא, מחולק","40 גרם קמח לבן","1 עלה דפנה","450 גרם תערובת דגים לפשטידה (בקלה, סלמון והדוק מעושן, ללא עור)","150 גרם שרימפס נא קלופים","150 גרם אפונה קפואה","2 כפות פטרוזיליה טרייה, קצוצה","50 גרם צ''דר מיושן, מגורר","0.5 כפית מלח","0.25 כפית פלפל שחור"}'::text[], E'{"חממו את התנור ל-200 מעלות (180 מעלות בטורבו). בשלו את תפוחי האדמה בסיר גדול עם מים מומלחים 15–18 דקות עד שהם רכים, סננו ומעכו עם 50 גרם מהחמאה ו-100 מ\\"ל מהחלב. תבלו בחצי מהמלח.","בינתיים המיסו את 40 הגרם הנותרים של החמאה בסיר על אש בינונית, ערבבו פנימה את הקמח ובשלו דקה אחת. הוסיפו בהדרגה, תוך טריפה, את 500 מ\\"ל החלב הנותרים, הוסיפו את עלה הדפנה ובשלו על אש קטנה תוך ערבוב 3–4 דקות עד שהרוטב חלק וסמיך. הוציאו את עלה הדפנה ותבלו בשארית המלח ובפלפל.","פזרו את הדגים הנאים, השרימפס והאפונה על תחתית תבנית אפייה של כ-2 ליטר. ערבבו את הפטרוזיליה לתוך הרוטב ויצקו אותו באופן אחיד.","מרחו את הפירה מעל, החל מהשוליים כדי לאטום, ואז חספסו את פני השטח במזלג ופזרו את הגבינה.","הניחו את התבנית על מגש אפייה ואפו 30–35 דקות, עד שהפשטידה זהובה ומבעבעת בשוליים, הדג אטום ומתפרק בקלות והשרימפס ורודים לגמרי. תנו לה לנוח 5 דקות לפני ההגשה.","להכנה מראש: צננו את הפשטידה המורכבת שלא נאפתה, כסו ושמרו במקרר עד 24 שעות, ואז אפו 45–50 דקות עד שהיא חמה מאוד במרכז."}'::text[], 'ai'),
  ('tablewise:catalog:v1:fish-pie', 'ru', 'Рыбный пирог', '{"1 кг рассыпчатого картофеля, очищенного и нарезанного крупными кусками","90 г сливочного масла, разделить","600 мл цельного молока, разделить","40 г пшеничной муки","1 лавровый лист","450 г рыбного ассорти (треска, лосось и копчёная пикша без кожи)","150 г сырых очищенных креветок","150 г замороженного горошка","2 ст. л. свежей петрушки, нарубленной","50 г выдержанного чеддера, натёртого","0,5 ч. л. соли","0,25 ч. л. чёрного перца"}'::text[], '{"Разогрейте духовку до 200 °C (180 °C с конвекцией). Отварите картофель в большой кастрюле подсоленной воды 15–18 минут до мягкости, слейте воду и разомните с 50 г масла и 100 мл молока. Посолите половиной соли.","Тем временем растопите оставшиеся 40 г масла в сотейнике на среднем огне, вмешайте муку и готовьте 1 минуту. Постепенно, взбивая, влейте оставшиеся 500 мл молока, добавьте лавровый лист и варите, помешивая, 3–4 минуты, пока соус не станет гладким и густым. Выньте лавровый лист и приправьте оставшейся солью и перцем.","Распределите сырую рыбу, креветки и горошек по дну формы для запекания объёмом около 2 литров. Вмешайте петрушку в соус и равномерно залейте.","Выложите пюре сверху, начиная с краёв, чтобы закрыть начинку, затем взрыхлите поверхность вилкой и посыпьте сыром.","Поставьте форму на противень и запекайте 30–35 минут, пока верх не станет золотистым, а по краям не забулькает, рыба не станет непрозрачной и легко расслаивающейся, а креветки — полностью розовыми. Дайте постоять 5 минут перед подачей.","Чтобы приготовить заранее, остудите собранный незапечённый пирог, накройте и уберите в холодильник до 24 часов, затем запекайте 45–50 минут, пока он не прогреется насквозь."}'::text[], 'ai'),
  ('tablewise:catalog:v1:flatbread-pizzas', 'he', 'פיצות על לחם שטוח עם עגבניות ומוצרלה', '{"300 גרם קמח תופח ועוד מעט לקימוח","300 גרם יוגורט טבעי","0.5 כפית מלח","1 כף שמן זית","150 גרם פסאטה","1 שן שום, כתושה","1 כפית אורגנו יבש","250 גרם מוצרלה, מסוננת וקרועה","150 גרם עגבניות שרי, חצויות","10 גרם עלי בזיליקום טרי, לא חובה"}'::text[], '{"חממו את התנור ל-240 מעלות (220 מעלות בטורבו) והכניסו שתי תבניות אפייה גדולות להתחמם.","ערבבו בקערה את הקמח, היוגורט והמלח לבצק רך. לושו קצרות על משטח מקומח עד שהבצק חלק, חלקו לארבעה ורדדו כל חלק לאליפסה דקה.","ערבבו את הפסאטה עם השום והאורגנו. הברישו את התבניות החמות בשמן והניחו עליהן את הלחמים השטוחים.","מרחו את רוטב העגבניות על הבסיסים, ואז הוסיפו את המוצרלה ועגבניות השרי.","אפו 10–12 דקות עד שהבסיסים פריכים מלמטה והגבינה מבעבעת. פזרו בזיליקום אם רוצים וחתכו לפרוסות."}'::text[], 'ai'),
  ('tablewise:catalog:v1:flatbread-pizzas', 'ru', 'Пиццы на лепёшках с томатами и моцареллой', '{"300 г самоподнимающейся муки и ещё немного для подпыла","300 г натурального йогурта","0,5 ч. л. соли","1 ст. л. оливкового масла","150 г пассаты","1 зубчик чеснока, раздавленный","1 ч. л. сушёного орегано","250 г моцареллы, обсушить и порвать","150 г томатов черри, разрезанных пополам","10 г свежих листьев базилика, по желанию"}'::text[], '{"Разогрейте духовку до 240 °C (220 °C с конвекцией) и поставьте в неё нагреваться два больших противня.","Смешайте муку, йогурт и соль в миске до мягкого теста. Коротко вымесите на присыпанной мукой поверхности до гладкости, затем разделите на четыре части и раскатайте каждую в тонкий овал.","Смешайте пассату с чесноком и орегано. Смажьте горячие противни маслом и выложите на них лепёшки.","Распределите томатный соус по основам, затем выложите моцареллу и томаты черри.","Выпекайте 10–12 минут, пока основы не станут хрустящими снизу, а сыр не начнёт пузыриться. По желанию посыпьте базиликом и нарежьте на куски."}'::text[], 'ai'),
  ('tablewise:catalog:v1:pork-schnitzel', 'he', 'שניצל חזיר', '{"750 גרם תפוחי אדמה צעירים, הגדולים חצויים","15 גרם חמאה","1 כף פטרוזיליה טרייה, קצוצה","4 סטייקים של מותן חזיר ללא עצם, שומן מוסר","50 גרם קמח לבן","0.5 כפית מלח","0.25 כפית פלפל שחור","2 ביצים","100 גרם פירורי לחם פנקו","6 כפות שמן צמחי","1 לימון, חתוך לפלחים"}'::text[], E'{"בשלו את תפוחי האדמה בסיר גדול עם מים מומלחים 15–18 דקות עד שהם רכים. סננו וערבבו עם החמאה והפטרוזיליה; שמרו חמים.","בינתיים הניחו כל סטייק בין שני דפי אפייה והכו במערוך עד לעובי של כ-5 מ\\"מ.","הכינו שלוש צלחות רדודות: הקמח מעורבב עם המלח והפלפל, הביצים טרופות ופירורי הלחם. צפו כל סטייק בקמח, אחר כך בביצה ואז בפירורים, תוך לחיצה כדי שיידבקו. שטפו ידיים וקרש אחרי טיפול בבשר חזיר נא.","חממו חצי מהשמן במחבת גדולה על אש בינונית-גבוהה. טגנו שני שניצלים 2–3 דקות מכל צד, עד שהם זהובים עמוקים ומבושלים לגמרי (לפחות 63 מעלות במרכז). הניחו על נייר סופג וחזרו עם שארית השמן והבשר.","תנו לשניצלים לנוח 3 דקות, ואז הגישו עם תפוחי האדמה ופלחי הלימון לסחיטה."}'::text[], 'ai'),
  ('tablewise:catalog:v1:pork-schnitzel', 'ru', 'Свиной шницель', '{"750 г молодого картофеля, крупные разрезать пополам","15 г сливочного масла","1 ст. л. свежей петрушки, нарубленной","4 стейка из свиной корейки без кости, срезать жир","50 г пшеничной муки","0,5 ч. л. соли","0,25 ч. л. чёрного перца","2 яйца","100 г панировочных сухарей панко","6 ст. л. растительного масла","1 лимон, нарезанный дольками"}'::text[], '{"Отварите картофель в большой кастрюле подсоленной воды 15–18 минут до мягкости. Слейте воду и перемешайте с маслом и петрушкой; держите в тепле.","Тем временем положите каждый стейк между двумя листами пергамента и отбейте скалкой до толщины около 5 мм.","Подготовьте три неглубокие миски: мука с солью и перцем, взбитые яйца и сухари. Обваляйте каждый стейк в муке, затем в яйце, затем в сухарях, прижимая, чтобы панировка держалась. Вымойте руки и доску после работы с сырой свининой.","Разогрейте половину масла в большой сковороде на огне выше среднего. Жарьте два шницеля по 2–3 минуты с каждой стороны до насыщенного золотистого цвета и полной готовности (не менее 63 °C в центре). Обсушите на бумажном полотенце и повторите с оставшимся маслом и свининой.","Дайте шницелям постоять 3 минуты, затем подавайте с картофелем и дольками лимона."}'::text[], 'ai'),
  ('tablewise:catalog:v1:rice-noodle-salad', 'he', 'סלט אטריות אורז בסגנון וייטנאמי', '{"400 גרם טופו קשה, מסונן ומיובש","1 כף קורנפלור","2 כפות שמן צמחי","200 גרם אטריות אורז","2 גזרים, חתוכים לגפרורים","1 מלפפון, חתוך לגפרורים","1 חסה ליטל ג''ם, פרוסה דק","15 גרם נענע טרייה, עלים בלבד","15 גרם כוסברה טרייה, עלים בלבד","50 גרם בוטנים קלויים, קצוצים גס","2 ליים, סחוטים","3 כפות טמרי (רוטב סויה ללא גלוטן)","1.5 כפות סוכר חום בהיר","3 כפות מים","1 צ''ילי אדום, קצוץ דק","1 שן שום, כתושה"}'::text[], E'{"הכינו את הרוטב: ערבבו בכד את מיץ הליים, הטמרי, הסוכר, המים, הצ''ילי והשום עד שהסוכר נמס.","חתכו את הטופו לקוביות של 2 ס\\"מ וערבבו עם הקורנפלור. טגנו בשמן במחבת גדולה על אש בינונית-גבוהה 8–10 דקות תוך הפיכה, עד שהוא זהוב ופריך מכל הצדדים. יצקו מעליו 2 כפות מהרוטב וערבבו.","בינתיים בשלו את אטריות האורז בסיר עם מים רותחים לפי ההוראות שעל האריזה, בדרך כלל 3–4 דקות. סננו, שטפו במים קרים וסננו היטב.","חלקו את החסה והאטריות לקערות והוסיפו מעל את הגזר, המלפפון, הטופו, הנענע והכוסברה.","יצקו את שארית הרוטב ופזרו את הבוטנים ממש לפני ההגשה."}'::text[], 'ai'),
  ('tablewise:catalog:v1:rice-noodle-salad', 'ru', 'Салат с рисовой лапшой по-вьетнамски', '{"400 г плотного тофу, слить и обсушить","1 ст. л. кукурузного крахмала","2 ст. л. растительного масла","200 г рисовой лапши","2 моркови, нарезанные соломкой","1 огурец, нарезанный соломкой","1 кочанчик салата литл джем, нашинкованный","15 г свежей мяты, только листья","15 г свежей кинзы, только листья","50 г жареного арахиса, крупно нарубленного","2 лайма, выжать сок","3 ст. л. тамари (соевый соус без глютена)","1,5 ст. л. светлого коричневого сахара","3 ст. л. воды","1 красный перец чили, мелко нарубленный","1 зубчик чеснока, раздавленный"}'::text[], '{"Приготовьте заправку: смешайте в кувшине сок лайма, тамари, сахар, воду, чили и чеснок, пока сахар не растворится.","Нарежьте тофу кубиками по 2 см и перемешайте с крахмалом. Жарьте в масле в большой сковороде на огне выше среднего 8–10 минут, переворачивая, до золотистой хрустящей корочки со всех сторон. Полейте 2 ст. л. заправки и перемешайте.","Тем временем отварите рисовую лапшу в кастрюле с кипящей водой по инструкции на упаковке, обычно 3–4 минуты. Откиньте, промойте холодной водой и хорошо обсушите.","Разложите салат и лапшу по мискам и выложите сверху морковь, огурец, тофу, мяту и кинзу.","Полейте оставшейся заправкой и посыпьте арахисом непосредственно перед подачей."}'::text[], 'ai'),
  ('tablewise:catalog:v1:slow-cooker-pulled-pork', 'he', 'חזיר מפורק בסיר בישול איטי', E'{"1.5 ק\\"ג כתף חזיר ללא עצם, ללא עור ושומן עודף","2 כפות סוכר חום רך","2 כפיות פפריקה מעושנת","1 כפית כמון טחון","1 כפית גרגירי שום","1.5 כפיות מלח","0.5 כפית פלפל שחור","1 בצל, פרוס","200 גרם פסאטה","2 כפות רסק עגבניות","3 כפות חומץ תפוחים","2 כפות דבש","6 לחמניות המבורגר, פרוסות","200 גרם קולסלו, לא חובה"}'::text[], '{"ערבבו בקערה קטנה את הסוכר, הפפריקה, הכמון, גרגירי השום, המלח והפלפל ושפשפו על כל הבשר. שטפו ידיים וקרש אחרי טיפול בבשר חזיר נא.","פזרו את הבצל על תחתית הסיר האיטי והניחו את הבשר מעליו.","טרפו יחד את הפסאטה, רסק העגבניות, חומץ התפוחים והדבש ויצקו על הבשר.","כסו ובשלו בעוצמה נמוכה 8 שעות (או בעוצמה גבוהה 5 שעות) עד שהבשר רך מאוד ומתפרק בקלות. הטמפרטורה תהיה הרבה מעל 63 מעלות.","הרימו את הבשר לקרש ופרקו אותו בשני מזלגות, תוך השלכת השומן. הסירו את השומן מהרוטב והחזירו את הבשר המפורק לסיר.","מלאו את הלחמניות, עם קולסלו אם רוצים. צננו שאריות בתוך שעתיים והקפיאו במנות עם מעט רוטב עד 3 חודשים; חממו עד שהן חמות מאוד."}'::text[], 'ai'),
  ('tablewise:catalog:v1:slow-cooker-pulled-pork', 'ru', 'Рваная свинина в медленноварке', '{"1,5 кг свиной лопатки без кости, без шкуры и лишнего жира","2 ст. л. мягкого коричневого сахара","2 ч. л. копчёной паприки","1 ч. л. молотой зиры","1 ч. л. гранулированного чеснока","1,5 ч. л. соли","0,5 ч. л. чёрного перца","1 луковица, нарезанная","200 г пассаты","2 ст. л. томатного пюре","3 ст. л. яблочного уксуса","2 ст. л. мёда","6 булочек для бургеров, разрезанных","200 г салата коулслоу, по желанию"}'::text[], '{"Смешайте сахар, паприку, зиру, чеснок, соль и перец в небольшой миске и натрите свинину со всех сторон. Вымойте руки и доску после работы с сырой свининой.","Распределите лук по дну медленноварки и положите сверху свинину.","Взбейте пассату, томатное пюре, яблочный уксус и мёд и полейте свинину.","Накройте и готовьте на низком режиме 8 часов (или на высоком 5 часов), пока свинина не станет очень мягкой и не будет легко распадаться. Температура будет намного выше 63 °C.","Переложите свинину на доску и разберите двумя вилками, удалив жир. Снимите жир с соуса и верните разобранное мясо в медленноварку.","Выложите в булочки, по желанию с коулслоу. Остудите остатки в течение 2 часов и заморозьте порциями с небольшим количеством соуса на срок до 3 месяцев; разогревайте до очень горячего состояния."}'::text[], 'ai'),
  ('tablewise:catalog:v1:tofu-vegetable-stir-fry', 'he', 'מוקפץ טופו וירקות', '{"300 גרם אורז יסמין","450 גרם טופו קשה במיוחד, מסונן ומיובש","3 כפיות קורנפלור, מחולקות","3 כפות טמרי (רוטב סויה ללא גלוטן)","1 כף סירופ מייפל","1 כף חומץ אורז","1 כפית שמן שומשום קלוי","4 כפות מים","3 כפות שמן צמחי, מחולקות","250 גרם פרחי ברוקולי","1 פלפל אדום, פרוס","1 גזר, חתוך למקלות דקים","150 גרם אפונת שלג","2 שיני שום, קצוצות דק","15 גרם ג''ינג''ר טרי, מגורר","3 בצלים ירוקים, פרוסים","1 כף שומשום, לא חובה"}'::text[], E'{"בשלו את האורז בסיר לפי ההוראות שעל האריזה ושמרו חם.","חתכו את הטופו לקוביות של 2 ס\\"מ וערבבו בקערה עם 2 כפיות מהקורנפלור. בקערה קטנה ערבבו את הטמרי, סירופ המייפל, החומץ, שמן השומשום, המים ושארית הקורנפלור להכנת הרוטב.","חממו 2 כפות מהשמן הצמחי בווק או במחבת גדולה על אש בינונית-גבוהה. טגנו את הטופו 8–10 דקות תוך הפיכה, עד שהוא פריך וזהוב מכל הצדדים. העבירו לצלחת.","הוסיפו את שארית השמן והקפיצו את הברוקולי, הפלפל והגזר 3 דקות. הוסיפו את אפונת השלג, השום והג''ינג''ר והקפיצו עוד 2 דקות, עד שהירקות רכים אך עדיין פריכים.","ערבבו את הרוטב, יצקו לווק ובעבעו דקה אחת עד שהוא מבריק. החזירו את הטופו, ערבבו לציפוי ופזרו בצל ירוק ושומשום. הגישו עם האורז."}'::text[], 'ai'),
  ('tablewise:catalog:v1:tofu-vegetable-stir-fry', 'ru', 'Тофу с овощами в воке', '{"300 г риса жасмин","450 г очень плотного тофу, слить и обсушить","3 ч. л. кукурузного крахмала, разделить","3 ст. л. тамари (соевый соус без глютена)","1 ст. л. кленового сиропа","1 ст. л. рисового уксуса","1 ч. л. поджаренного кунжутного масла","4 ст. л. воды","3 ст. л. растительного масла, разделить","250 г соцветий брокколи","1 красный перец, нарезанный","1 морковь, нарезанная тонкими брусочками","150 г сахарного горошка","2 зубчика чеснока, мелко нарубленных","15 г свежего имбиря, натёртого","3 стебля зелёного лука, нарезанных","1 ст. л. кунжута, по желанию"}'::text[], '{"Отварите рис в кастрюле по инструкции на упаковке и держите в тепле.","Нарежьте тофу кубиками по 2 см и перемешайте в миске с 2 ч. л. крахмала. В маленькой миске смешайте тамари, кленовый сироп, уксус, кунжутное масло, воду и оставшийся крахмал для соуса.","Разогрейте 2 ст. л. растительного масла в воке или большой сковороде на огне выше среднего. Жарьте тофу 8–10 минут, переворачивая, до хрустящей золотистой корочки со всех сторон. Переложите на тарелку.","Добавьте оставшееся масло и обжаривайте брокколи, перец и морковь 3 минуты. Добавьте сахарный горошек, чеснок и имбирь и жарьте ещё 2 минуты, пока овощи не станут мягкими, но ещё хрустящими.","Перемешайте соус, влейте в вок и прогрейте 1 минуту до блеска. Верните тофу, перемешайте, затем посыпьте зелёным луком и кунжутом. Подавайте с рисом."}'::text[], 'ai'),
  ('tablewise:real:v1:baked-salmon', 'he', 'סלמון אפוי פשוט', '{"4 פילה סלמון ללא עור","1 כף שמן זית","מלח ופלפל שחור לפי הטעם","עשבי תיבול קצוצים להגשה, לא חובה","פרוסות לימון להגשה, לא חובה","ברוקולי באדים להגשה, לא חובה"}'::text[], '{"חממו את התנור ל-180 מעלות (160 מעלות בטורבו). הברישו את הסלמון בשמן זית ותבלו.","סדרו את הפילה בתבנית חסינת תנור. כסו לקבלת מרקם רך יותר, או השאירו ללא כיסוי לפני שטח צלוי קלות.","אפו 10–15 דקות, בהתאם לעובי, עד שהדג אטום ומתפרק בקלות.","הגישו עם עשבי התיבול, הלימון והברוקולי המאודה בנפרד לפי הרצון. כמות התוספות אינה קבועה במקור."}'::text[], 'ai'),
  ('tablewise:real:v1:baked-salmon', 'ru', 'Простой запечённый лосось', '{"4 филе лосося без кожи","1 ст. л. оливкового масла","Соль и чёрный перец по вкусу","Рубленая зелень для подачи, по желанию","Ломтики лимона для подачи, по желанию","Брокколи на пару для подачи, по желанию"}'::text[], '{"Разогрейте духовку до 180 °C (160 °C с конвекцией). Смажьте лосось оливковым маслом и приправьте.","Выложите филе в жаропрочную форму. Накройте, чтобы рыба получилась мягче, или оставьте открытой для лёгкой корочки.","Запекайте 10–15 минут, в зависимости от толщины, пока рыба не станет непрозрачной и не начнёт легко расслаиваться.","Подавайте с зеленью, лимоном и отдельно приготовленной на пару брокколи по желанию. Количество гарнира в источнике не указано."}'::text[], 'ai'),
  ('tablewise:real:v1:chicken-curry', 'he', 'קארי עוף קל', '{"2 כפות שמן חמניות","1 בצל, פרוס דק","2 שיני שום, כתושות","1 חתיכת ג''ינג''ר בגודל אגודל, מגוררת","6 ירכי עוף ללא עור וללא עצם","3 כפות משחת קארי בחריפות בינונית","400 גרם עגבניות קצוצות משומרות","100 גרם יוגורט יווני","1 צרור קטן כוסברה, קצוצה","50 גרם שקדים טחונים","מלח לפי הטעם","לחם נאן או אורז בסמטי מבושל להגשה, לא חובה"}'::text[], E'{"במחבת גדולה רככו את הבצל בשמן עם קורט מלח על אש בינונית 8–10 דקות.","ערבבו פנימה את השום והג''ינג''ר לדקה אחת. חתכו את העוף לחתיכות של כ-3 ס\\"מ וטגנו במחבת 5 דקות.","הוסיפו את משחת הקארי, העגבניות ו-250 מ\\"ל מים. הביאו לרתיחה ובשלו ללא מכסה 25–30 דקות, עד שהרוטב מסמיך והעוף מבושל לגמרי.","ערבבו פנימה את היוגורט, הכוסברה והשקדים הטחונים. תקנו תיבול והגישו; נאן או אורז מבושל בנפרד לפי הרצון."}'::text[], 'ai'),
  ('tablewise:real:v1:chicken-curry', 'ru', 'Простое куриное карри', '{"2 ст. л. подсолнечного масла","1 луковица, тонко нарезанная","2 зубчика чеснока, раздавленных","1 кусочек имбиря размером с большой палец, натёртый","6 куриных бёдер без кости и кожи","3 ст. л. пасты карри средней остроты","400 г консервированных резаных томатов","100 г греческого йогурта","1 небольшой пучок кинзы, нарубленной","50 г молотого миндаля","Соль по вкусу","Лепёшка наан или готовый рис басмати для подачи, по желанию"}'::text[], '{"В большой сковороде готовьте лук в масле со щепоткой соли на среднем огне 8–10 минут до мягкости.","Вмешайте чеснок и имбирь на 1 минуту. Нарежьте курицу кусками примерно по 3 см и обжаривайте на сковороде 5 минут.","Добавьте пасту карри, томаты и 250 мл воды. Доведите до кипения, затем тушите без крышки 25–30 минут, пока соус не загустеет, а курица не приготовится полностью.","Вмешайте йогурт, кинзу и молотый миндаль. Доведите до вкуса и подавайте; наан или отдельно приготовленный рис — по желанию."}'::text[], 'ai'),
  ('tablewise:real:v1:coconut-chickpea-curry', 'he', 'קארי חומוס וקייל בחלב קוקוס', '{"1.5 כפות אבקת קארי","1 כפית כמון","1 בצל צהוב, קצוץ לקוביות","2 שיני שום, קצוצות דק","1 כפית ג''ינג''ר טרי, מגורר","2 כפות שמן זית","2 פחיות גרגרי חומוס (15 אונקיות כל אחת), מסוננות","1 פחית רוטב עגבניות (8 אונקיות)","1 פחית חלב קוקוס מלא (13.5 אונקיות)","4 אונקיות קייל, קצוץ","מלח לפי הטעם","אורז מבושל או לחם להגשה, לא חובה"}'::text[], '{"קצצו את הבצל לקוביות, קצצו דק את השום, גררו את הג''ינג''ר וקצצו את הקייל.","קלו את אבקת הקארי והכמון במחבת עמוקה יבשה על אש בינונית-נמוכה כדקה.","הוסיפו את שמן הזית, הבצל, השום והג''ינג''ר; רככו כ-5 דקות. ערבבו פנימה את גרגרי החומוס המסוננים, רוטב העגבניות וחלב הקוקוס.","הביאו לרתיחה עדינה, הנמיכו את האש ובשלו 15 דקות תוך ערבוב מדי פעם.","הוסיפו את הקייל ובשלו עוד כ-5 דקות, עד שהוא מתרכך. המליחו לפי הטעם והגישו בצד אורז או לחם לפי הרצון."}'::text[], 'ai'),
  ('tablewise:real:v1:coconut-chickpea-curry', 'ru', 'Карри из нута и кейла на кокосовом молоке', '{"1,5 ст. л. порошка карри","1 ч. л. зиры","1 жёлтая луковица, нарезанная кубиками","2 зубчика чеснока, мелко нарубленных","1 ч. л. свежего имбиря, натёртого","2 ст. л. оливкового масла","2 банки нута (по 15 унц.), слить жидкость","1 банка томатного соуса (8 унц.)","1 банка жирного кокосового молока (13,5 унц.)","4 унц. кейла, нарезанного","Соль по вкусу","Готовый рис или хлеб для подачи, по желанию"}'::text[], '{"Нарежьте лук кубиками, мелко нарубите чеснок, натрите имбирь и нарежьте кейл.","Обжарьте порошок карри и зиру на сухой глубокой сковороде на огне ниже среднего примерно 1 минуту.","Добавьте оливковое масло, лук, чеснок и имбирь; готовьте до мягкости около 5 минут. Вмешайте нут, томатный соус и кокосовое молоко.","Доведите до лёгкого кипения, убавьте огонь и готовьте 15 минут, иногда помешивая.","Добавьте кейл и готовьте ещё около 5 минут, до мягкости. Посолите по вкусу и по желанию подайте отдельно приготовленный рис или хлеб."}'::text[], 'ai'),
  ('tablewise:real:v1:lentil-leek-soup', 'he', 'מרק עדשים כתומות, גזר וכרישה', '{"2 ליטר ציר ירקות","150 גרם עדשים כתומות","6 גזרים, קצוצים דק","2 כרישות בינוניות, פרוסות (כ-300 גרם)","1 חופן קטן פטרוזיליה, קצוצה","מלח ופלפל שחור לפי הטעם"}'::text[], '{"חממו את ציר הירקות בסיר גדול וערבבו פנימה את העדשים הכתומות.","הביאו לרתיחה ותנו לעדשים להתחיל להתרכך כמה דקות.","הוסיפו את הגזר והכרישה, תבלו לפי הטעם, כסו ובשלו על אש קטנה 45–60 דקות עד שהירקות רכים והעדשים מתפרקות.","פזרו פטרוזיליה על כל מנה. המקור מתיר גם ציר חזיר; גרסה זו משתמשת באפשרות הצמחונית של ציר ירקות."}'::text[], 'ai'),
  ('tablewise:real:v1:lentil-leek-soup', 'ru', 'Суп из красной чечевицы, моркови и лука-порея', '{"2 литра овощного бульона","150 г красной чечевицы","6 морковок, мелко нарезанных","2 средних стебля лука-порея, нарезанных (около 300 г)","1 небольшая горсть петрушки, нарубленной","Соль и чёрный перец по вкусу"}'::text[], '{"Разогрейте овощной бульон в большой кастрюле и вмешайте красную чечевицу.","Доведите до кипения и дайте чечевице начать размягчаться несколько минут.","Добавьте морковь и лук-порей, приправьте по вкусу, накройте и варите на слабом огне 45–60 минут, пока овощи не станут мягкими, а чечевица не разварится.","Посыпьте каждую порцию петрушкой. Источник допускает и бульон на ветчине; в этой версии выбран вегетарианский овощной бульон."}'::text[], 'ai'),
  ('tablewise:real:v1:salmon-egg-fried-rice', 'he', 'אורז מטוגן עם סלמון וביצה', '{"1 חתיכת ג''ינג''ר בגודל אגודל, מגוררת","1–2 שיני שום, מגוררות","2 כפות רוטב סויה דל נתרן","0.5 כף חומץ אורז","2 כפות שמן צמחי","1 גזר גדול, קצוץ","175 גרם תירס גמדי ואפונת שלג, קצוצים","2 פילה סלמון מעושן ללא עור","250 גרם שקית אורז בסמטי מלא מבושל","2 ביצים","רוטב חריף להגשה, לא חובה"}'::text[], '{"ערבבו בקערה את הג''ינג''ר, השום, רוטב הסויה והחומץ.","חממו ווק גדול עם כף אחת שמן. הוסיפו את הגזר, הירקות והסלמון; בשלו את הדג כ-2 דקות מכל צד.","ערבבו פנימה את האורז המוכן תוך פירוק הדג לפתיתים. דחפו את התערובת הצידה, הוסיפו את שארית השמן וטרפו את הביצים במקום הפנוי.","ערבבו הכול יחד עם תערובת הסויה וחממו היטב כמה דקות. הגישו רוטב חריף בצד."}'::text[], 'ai'),
  ('tablewise:real:v1:salmon-egg-fried-rice', 'ru', 'Жареный рис с лососем и яйцом', '{"1 кусочек имбиря размером с большой палец, натёртый","1–2 зубчика чеснока, натёртых","2 ст. л. соевого соуса с пониженным содержанием соли","0,5 ст. л. рисового уксуса","2 ст. л. растительного масла","1 крупная морковь, нарезанная","175 г мини-кукурузы и сахарного горошка, нарезанных","2 филе копчёного лосося без кожи","250 г готового бурого риса басмати в пакете","2 яйца","Острый соус для подачи, по желанию"}'::text[], '{"Смешайте в миске имбирь, чеснок, соевый соус и уксус.","Разогрейте большой вок с 1 столовой ложкой масла. Добавьте морковь, овощную смесь и лосось; готовьте рыбу примерно по 2 минуты с каждой стороны.","Вмешайте готовый рис, разделяя рыбу на кусочки. Сдвиньте смесь в сторону, добавьте оставшееся масло и пожарьте яйца-болтунью на освободившемся месте.","Перемешайте всё с соевой смесью и хорошо прогрейте несколько минут. Острый соус подайте отдельно."}'::text[], 'ai'),
  ('tablewise:real:v1:sichuan-beef-stir-fry', 'he', 'מוקפץ בקר עם פלפל סצ''ואן', '{"2 כפות שמן קנולה","300 גרם סטייק, פרוס דק","1 כף קורנפלור","2 פלפלים בצבעים שונים, פרוסים","200 גרם תירס גמדי, חצוי","2 בצלים סגולים קטנים, פרוסים","0.5 כפית פתיתי צ''ילי","1 כפית פלפל סצ''ואן, טחון","2 כפות רוטב סויה כהה דל נתרן","1 כף שמן צ''ילי, לא חובה","300 גרם אורז בסמטי מלא מבושל"}'::text[], E'{"טחנו את פלפל הסצ''ואן במכתש ועלי.","חממו כף אחת שמן קנולה בווק גדול. הוסיפו את הסטייק והקורנפלור, ערבבו לציפוי וטגנו 2–3 דקות עד להשחמה; העבירו לצלחת.","הוסיפו את שארית השמן, הפלפלים, התירס הגמדי והבצל. הקפיצו 3–4 דקות, ואז החזירו את הבקר עם הנוזלים שלו, פתיתי הצ''ילי ופלפל הסצ''ואן.","בשלו דקה אחת, הוסיפו את רוטב הסויה ו-50 מ\\"ל מים וערבבו עד שהרוטב מצפה הכול. הגישו עם האורז המוכן ועם שמן צ''ילי לפי הרצון."}'::text[], 'ai'),
  ('tablewise:real:v1:sichuan-beef-stir-fry', 'ru', 'Говядина с сычуаньским перцем в воке', '{"2 ст. л. рапсового масла","300 г стейка, тонко нарезанного","1 ст. л. кукурузного крахмала","2 разноцветных перца, нарезанных","200 г мини-кукурузы, разрезанной пополам","2 небольшие красные луковицы, нарезанные","0,5 ч. л. хлопьев чили","1 ч. л. сычуаньского перца, молотого","2 ст. л. тёмного соевого соуса с пониженным содержанием соли","1 ст. л. масла чили, по желанию","300 г готового бурого риса басмати"}'::text[], '{"Измельчите сычуаньский перец в ступке.","Разогрейте 1 столовую ложку рапсового масла в большом воке. Добавьте стейк и крахмал, перемешайте, чтобы покрыть, и обжаривайте 2–3 минуты до румяности; переложите на тарелку.","Добавьте оставшееся масло, перец, мини-кукурузу и лук. Обжаривайте 3–4 минуты, затем верните говядину с соком, хлопья чили и сычуаньский перец.","Готовьте 1 минуту, добавьте соевый соус и 50 мл воды и перемешивайте, пока соус не покроет всё. Подавайте с готовым рисом и маслом чили по желанию."}'::text[], 'ai'),
  ('tablewise:real:v1:spaghetti-meatballs', 'he', 'ספגטי עם קציצות בקר ונקניקיות', '{"8 נקניקיות, ללא קליפה","500 גרם בשר בקר טחון","4 שיני שום, כתושות","1 צרור קטן פטרוזיליה, קצוצה","3 כפות פירורי לחם יבשים","1 ביצה, טרופה","קמח לבן לגלגול","4 כפות שמן חמניות","2 פחיות עגבניות קצוצות","1 קורט סוכר","500 גרם ספגטי","פרמזן מגורר להגשה","מלח ופלפל שחור לפי הטעם"}'::text[], '{"ערבבו בקערה גדולה את בשר הנקניקיות, הבקר, חצי מהשום והפטרוזיליה, פירורי הלחם והביצה. תבלו וערבבו.","על קרש חיתוך מקומח גלגלו כדורים בגודל כף קינוח. השחימו במנות במחבת גדולה עם 3 כפות שמן והניחו בצד.","השליכו את השומן העודף ונקו את המחבת. חממו את שארית השמן, טגנו קצרות את שארית השום, ואז בשלו את העגבניות 5 דקות; תבלו בסוכר, מלח ופלפל.","החזירו את הקציצות, כסו ובשלו על אש קטנה כ-30 דקות, תוך הפיכה ברוטב והוספת מעט מים לפי הצורך.","בשלו את הספגטי בסיר במהלך 15 הדקות האחרונות. ערבבו את הפטרוזיליה לתוך הרוטב והגישו מעל הפסטה המסוננת עם פרמזן."}'::text[], 'ai'),
  ('tablewise:real:v1:spaghetti-meatballs', 'ru', 'Спагетти с фрикадельками из говядины и колбасок', '{"8 колбасок, без оболочки","500 г говяжьего фарша","4 зубчика чеснока, раздавленных","1 небольшой пучок петрушки, нарубленной","3 ст. л. сухих панировочных сухарей","1 яйцо, взбитое","Пшеничная мука для обваливания","4 ст. л. подсолнечного масла","2 банки резаных томатов","1 щепотка сахара","500 г спагетти","Тёртый пармезан для подачи","Соль и чёрный перец по вкусу"}'::text[], '{"Смешайте в большой миске колбасный фарш, говядину, половину чеснока и петрушки, сухари и яйцо. Приправьте и перемешайте.","На присыпанной мукой разделочной доске скатайте шарики размером с десертную ложку. Обжарьте партиями в большой сковороде с 3 столовыми ложками масла и отложите.","Слейте лишний жир и очистите сковороду. Разогрейте оставшееся масло, быстро обжарьте оставшийся чеснок, затем готовьте томаты 5 минут; приправьте сахаром, солью и перцем.","Верните фрикадельки, накройте и тушите на слабом огне около 30 минут, переворачивая в соусе и при необходимости добавляя немного воды.","За последние 15 минут отварите спагетти в кастрюле. Вмешайте петрушку в соус и подавайте поверх откинутой пасты с пармезаном."}'::text[], 'ai'),
  ('tablewise:real:v1:spanish-omelette', 'he', 'חביתה ספרדית עם תפוחי אדמה ופלפל', '{"500 גרם תפוחי אדמה מוצקים","חמאה: קוביה ועוד מעט למחבת","2 בצלים קטנים, פרוסים דק","1 פלפל אדום, קצוץ","8–9 ביצים","25 גרם עירית","מלח ופלפל שחור לפי הטעם"}'::text[], E'{"פרסו את תפוחי האדמה לפרוסות בעובי של כ-0.5 ס\\"מ. בשלו בעדינות את הבצלים בחמאה במחבת בקוטר של כ-24 ס\\"מ 10–15 דקות, ואז הוסיפו את הפלפל ל-5 דקות.","בינתיים רככו את תפוחי האדמה בסיר עם מים רותחים 8–10 דקות, ואז סננו.","טרפו את הביצים בכד, הוסיפו תיבול ועירית קצוצה. חממו את הגריל והוסיפו למחבת עוד מעט חמאה ואת תפוחי האדמה.","יצקו את הביצים ובשלו בעדינות כ-15 דקות עד שהחביתה כמעט מוצקה ומשחימה מלמטה.","סיימו מתחת לגריל 1–2 דקות. היזהרו מהידית החמה; השתמשו במחבת מתאימה. הנתונים שומרים את זמן הבישול שציין המוציא לאור — 30 דקות."}'::text[], 'ai'),
  ('tablewise:real:v1:spanish-omelette', 'ru', 'Испанский омлет с картофелем и перцем', '{"500 г картофеля с плотной мякотью","Сливочное масло: кусочек и ещё немного для сковороды","2 небольшие луковицы, тонко нарезанные","1 красный перец, нарезанный","8–9 яиц","25 г зелёного лука-резанца","Соль и чёрный перец по вкусу"}'::text[], '{"Нарежьте картофель ломтиками толщиной около 0,5 см. Томите лук в масле на сковороде диаметром около 24 см 10–15 минут, затем добавьте перец на 5 минут.","Тем временем размягчите картофель в кастрюле с кипящей водой 8–10 минут, затем слейте воду.","Взбейте яйца в кувшине, добавьте соль, перец и нарезанный лук-резанец. Разогрейте гриль и добавьте на сковороду ещё немного масла и картофель.","Влейте яйца и готовьте на слабом огне около 15 минут, пока омлет почти не схватится и не подрумянится снизу.","Доведите под грилем 1–2 минуты. Берегитесь горячей ручки; используйте подходящую сковороду. В данных сохранено указанное издателем время готовки — 30 минут."}'::text[], 'ai'),
  ('tablewise:real:v1:sundried-tomato-pasta', 'he', 'פסטה קרמית עם עגבניות מיובשות בסיר אחד', '{"0.5 כוס עגבניות מיובשות","2 כפות חמאה","2 שיני שום, קצוצות דק","8 אונקיות פטוצ''יני","0.5 כפית בזיליקום יבש","פלפל שחור לפי הטעם","2 כוסות ציר עוף","2 אונקיות גבינת שמנת","1 כוס חלב מלא","0.25 כוס פרמזן מגורר"}'::text[], '{"קצצו את העגבניות המיובשות. המיסו את החמאה במחבת עמוקה וטגנו בעדינות את השום כדקה.","הוסיפו את הפסטה, העגבניות, הבזיליקום, הפלפל וציר העוף. שברו את הפסטה במידת הצורך כדי שתהיה בתוך הנוזל.","כסו, הביאו לרתיחה ואז הנמיכו לבעבוע עדין. ערבבו כל כמה דקות והחזירו את המכסה.","בשלו 7–10 דקות עד שהפסטה רכה ורוב הציר נספג. על אש נמוכה המיסו פנימה את גבינת השמנת, ואז ערבבו פנימה את החלב והפרמזן כדי להשלים את הרוטב."}'::text[], 'ai'),
  ('tablewise:real:v1:sundried-tomato-pasta', 'ru', 'Сливочная паста с вялеными томатами в одной кастрюле', '{"0,5 стак. вяленых томатов","2 ст. л. сливочного масла","2 зубчика чеснока, мелко нарубленных","8 унц. феттучине","0,5 ч. л. сушёного базилика","Чёрный перец по вкусу","2 стак. куриного бульона","2 унц. сливочного сыра","1 стак. цельного молока","0,25 стак. тёртого пармезана"}'::text[], '{"Нарежьте вяленые томаты. Растопите масло в глубокой сковороде и слегка обжарьте чеснок около 1 минуты.","Добавьте пасту, томаты, базилик, перец и куриный бульон. При необходимости разломайте пасту, чтобы она была в жидкости.","Накройте крышкой, доведите до кипения, затем убавьте огонь до слабого. Помешивайте каждые несколько минут и снова накрывайте.","Готовьте 7–10 минут, пока паста не станет мягкой, а бульон почти не впитается. На слабом огне растопите сливочный сыр, затем вмешайте молоко и пармезан, чтобы получился соус."}'::text[], 'ai'),
  ('tablewise:synthetic:v1:002', 'he', 'לינגוויני עם סרדינים', '{"250 גרם פסטה יבשה","1 קופסת סרדינים או מקרל, מסוננת (או 300 גרם מולים נקיים)","2 שיני שום, קצוצות דק","200 גרם עגבניות שרי","2 כפות שמן זית","1 כף מיץ לימון","פטרוזיליה קצוצה לפי הטעם"}'::text[], '{"בשלו את הפסטה במים מומלחים ושמרו מעט ממי הבישול.","חממו שמן ושום, ואז רככו את העגבניות במחבת.","הוסיפו את הדג וחממו, או בשלו את המולים עד שהם נפתחים; השליכו מולים שלא נפתחו.","ערבבו עם הפסטה, מיץ הלימון והפטרוזיליה; דללו במי הפסטה."}'::text[], 'ai'),
  ('tablewise:synthetic:v1:002', 'ru', 'Лингвини с сардинами', '{"250 г сухой пасты","1 банка сардин или скумбрии, слить жидкость (или 300 г очищенных мидий)","2 зубчика чеснока, мелко нарубленных","200 г томатов черри","2 ст. л. оливкового масла","1 ст. л. лимонного сока","Рубленая петрушка по вкусу"}'::text[], '{"Отварите пасту в подсоленной воде и оставьте немного воды от варки.","Прогрейте масло с чесноком, затем размягчите томаты на сковороде.","Добавьте рыбу и прогрейте или готовьте мидии, пока не раскроются; нераскрывшиеся мидии выбросьте.","Перемешайте с пастой, лимонным соком и петрушкой; разбавьте водой от пасты."}'::text[], 'ai'),
  ('tablewise:synthetic:v1:006', 'he', 'פסטה ארביאטה פשוטה', '{"250 גרם פסטה יבשה","2 כפות שמן זית","2 שיני שום, קצוצות דק","300 גרם עגבניות, קצוצות","1 קישוא קטן או פלפל, קצוץ לקוביות","1 כפית עשבי תיבול יבשים","מלח ופלפל לפי הטעם"}'::text[], '{"בשלו את הפסטה לפי ההוראות שעל האריזה; סננו.","חממו שמן, הזהיבו את השום והירקות עד שהם מתרככים.","הוסיפו את העגבניות ועשבי התיבול ובשלו על אש קטנה 10 דקות.","ערבבו את הרוטב עם הפסטה; תבלו והגישו."}'::text[], 'ai'),
  ('tablewise:synthetic:v1:006', 'ru', 'Простая паста арраббьята', '{"250 г сухой пасты","2 ст. л. оливкового масла","2 зубчика чеснока, мелко нарубленных","300 г томатов, нарезанных","1 небольшой цукини или сладкий перец, нарезанный кубиками","1 ч. л. сушёных трав","Соль и перец по вкусу"}'::text[], '{"Отварите пасту по инструкции на упаковке; откиньте.","Разогрейте масло, обжарьте чеснок и овощи до мягкости.","Добавьте томаты и травы и тушите 10 минут.","Смешайте соус с пастой; приправьте и подавайте."}'::text[], 'ai'),
  ('tablewise:synthetic:v1:021', 'he', 'פסטה עם פטה ועגבניות', '{"250 גרם פסטה יבשה","2 כפות שמן זית","2 שיני שום, קצוצות דק","300 גרם עגבניות, קצוצות","1 קישוא קטן או פלפל, קצוץ לקוביות","1 כפית עשבי תיבול יבשים","מלח ופלפל לפי הטעם"}'::text[], '{"בשלו את הפסטה לפי ההוראות שעל האריזה; סננו.","חממו שמן, הזהיבו את השום והירקות עד שהם מתרככים.","הוסיפו את העגבניות ועשבי התיבול ובשלו על אש קטנה 10 דקות.","ערבבו את הרוטב עם הפסטה; תבלו והגישו."}'::text[], 'ai'),
  ('tablewise:synthetic:v1:021', 'ru', 'Паста с фетой и томатами', '{"250 г сухой пасты","2 ст. л. оливкового масла","2 зубчика чеснока, мелко нарубленных","300 г томатов, нарезанных","1 небольшой цукини или сладкий перец, нарезанный кубиками","1 ч. л. сушёных трав","Соль и перец по вкусу"}'::text[], '{"Отварите пасту по инструкции на упаковке; откиньте.","Разогрейте масло, обжарьте чеснок и овощи до мягкости.","Добавьте томаты и травы и тушите 10 минут.","Смешайте соус с пастой; приправьте и подавайте."}'::text[], 'ai'),
  ('tablewise:synthetic:v1:050', 'he', 'כריך פרנץ'' טוסט בסגנון מישיגן', E'{"200 גרם קמח לבן","80 גרם סוכר","2 ביצים","100 מ\\"ל חלב","80 מ\\"ל שמן ניטרלי","1 כפית אבקת אפייה","1 כפית תמצית וניל"}'::text[], '{"חממו את התנור ל-180 מעלות (356°F) והכינו תבנית אפייה או תבנית מאפינס.","טרפו את הביצים, החלב, השמן, הסוכר והווניל.","קפלו פנימה את הקמח ואבקת האפייה רק עד שהתערובת אחידה.","אפו עד להזהבה ועד ששיפוד יוצא נקי; צננו לפני ההגשה."}'::text[], 'ai'),
  ('tablewise:synthetic:v1:050', 'ru', 'Мичиганский сэндвич из французского тоста', '{"200 г пшеничной муки","80 г сахара","2 яйца","100 мл молока","80 мл растительного масла без запаха","1 ч. л. разрыхлителя","1 ч. л. ванильного экстракта"}'::text[], '{"Разогрейте духовку до 180 °C (356 °F) и подготовьте форму для выпечки или для маффинов.","Взбейте яйца, молоко, масло, сахар и ваниль.","Аккуратно вмешайте муку и разрыхлитель до однородности.","Выпекайте до золотистого цвета, пока шпажка не будет выходить сухой; остудите перед подачей."}'::text[], 'ai')
) AS v(recipe_id, language, title, ingredients, steps, translated_by)
WHERE EXISTS (SELECT 1 FROM "recipes" r WHERE r.id = v.recipe_id)
ON CONFLICT ("recipe_id", "language") DO NOTHING;

-- What production now has (expect up to 40 rows, 20 per language, for the recipes it holds).
SELECT "language", count(*) FROM "recipe_translations" GROUP BY 1 ORDER BY 1;
